from datetime import datetime, timedelta
def format_date(target_date: datetime) -> str:
    now = datetime.now()
    time_diff = target_date - now
    abs_diff = abs(time_diff)
    one_hour = timedelta(hours=1)
    one_day = timedelta(days=1)
    yesterday = now - one_day
    tomorrow = now + one_day
    future_time = time_diff.total_seconds() > 0
    if abs_diff < one_hour:
        minutes = abs_diff.seconds // 60
        if minutes == 1:
            return "1分钟后" if future_time else "1分钟前"
        else:
            return f"{'还有' if future_time else ''}{minutes}分钟"
    elif abs_diff < one_day:
        if target_date.date() == now.date():
            hours = abs_diff.seconds // 3600
            if hours == 1:
                return f"{'还有' if future_time else ''}1个小时，在{target_date.strftime('%p %I:%M')}"
            else:
                return f"{'还有' if future_time else ''}{hours}个小时，在{target_date.strftime('%p %I:%M')}"
        elif target_date.date() == yesterday.date():
            return f"昨天{target_date.strftime('%p %I:%M')}"
        else:
            return f"明天{target_date.strftime('%p %I:%M')}" if future_time else f"昨天{target_date.strftime('%p %I:%M')}"
    else:
