            if target_date.hour < 12:
                return f"明天早上{target_date.strftime('%p %I:%M')}"
            elif target_date.hour < 18:
                return f"明天下午{target_date.strftime('%p %I:%M')}"
            else:
                return f"明天晚上{target_date.strftime('%p %I:%M')}"
        else:
            days = abs_diff.days
            if days == 1:
                return f"{'还有' if future_time else ''}1天，在{target_date.strftime('%p %I:%M')}"
            else:
                return f"{'还有' if future_time else ''}{days}天，在{target_date.strftime('%p %I:%M')}"
def get_time_period(date: datetime) -> str:
